with filtered as (select *, coalesce(country, 'unassigned') as country_filled, case when browser in ('Edge', 'Safari') then 'Core' else 'Other' end as browser_group, coalesce(country, 'UNKNOWN') as country_clean from sessions where country is not null), with_gaps as (select *, case when lag(started_at) over (partition by customer_id order by started_at, id) is null or started_at > lag(started_at) over (partition by customer_id order by started_at, id) + interval '30' day then 1 else 0 end as new_group_flag from filtered), islands as (select id, customer_id, device, browser, started_at, country, browser_group, sum(new_group_flag) over (partition by customer_id order by started_at, id rows between unbounded preceding and current row) as session_no from with_gaps) select device, date_trunc('quarter', started_at) as quarter_start, customer_id, round(sum(session_no) / nullif(count(case when browser = 'Edge' then 1 end), 0), 2) as session_no_per_edge, count(*) as event_count, approx_percentile(session_no, array(0.25, 0.5, 0.75)) as session_no_quartiles from islands group by grouping sets ((device, date_trunc('quarter', started_at), customer_id), (device, date_trunc('quarter', started_at)), ())
